package com.tainted.community.blackbox;

import static com.tainted.community.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.community.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.community.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;


/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller CommunityController (src/main/java/com/tainted/community/web/CommunityController.java)
 * @target-api GET /internal/posts/{id}
 *
 * analyze-auth-flow: auth_type=none (인터셉터/필터/시큐리티 클래스 없음) -> auth.pattern=none.
 * detect-external-calls --include-di-analysis: depth 3까지 external_calls=0, 전 의존성 REAL(PostRepository/CommentRepository/CommunityEventPublisher/IdGenerator/Clock) -> WireMock 스텁 불필요.
 * DB: table `post` (PK id VARCHAR(64)); getPost -> CommunityService.getPost -> PostRepository.findById, 없으면 PostNotFoundException -> GlobalExceptionHandler(404, application/problem+json: type/title/status/detail).
 * RED 파라미터: id (DB_WHERE). VTC 표준 6종 중 NULL은 경로변수 특성상 EMPTY와 동일 관측치(trailing slash, PathPatternParser가 빈 세그먼트를 {id}에 매칭하지 않아 컨트롤러 도달 전 404)로 병합 처리 -> VTC_id_EMPTY 하나로 커버.
 * generate-test-plan의 ATC_code400(제네릭 extract-test-scenarios 산출)은 소스 직접 검증 결과 실제 분기 없음(GET 핸들러에 @Valid/@RequestBody 없어 MethodArgumentNotValidException 유발 불가) -> 제외.
 * NTC 3건은 서로 다른 fixture 행(모든 문자열/숫자 필드 리터럴 상이)을 equalTo/equalToInt로 검증. id/createdAt은 테스트별 결정적 시드/픽스처 파생값이라 renderer 지원 matcher(equalTo/equalToInt/containsString/notNullValue)로는 정확한 사전 예측이 어려워 containsString(접두사/날짜부분)으로 검증.
 * moodEmoji nullable 케이스(NTC_getPost_nullMoodEmoji)는 renderer가 JSON null 값 assertion(nullValue)을 지원하지 않아 해당 필드 검증을 생략하고 200 상태 + 나머지 필드 검증으로 널 허용 경로의 무장애 동작을 확인.
 * VTC_id_EMPTY는 컨트롤러 진입 전 라우팅 단계에서 404가 발생할 수 있어 body assertion 없이 statusCode(404)만 검증. 나머지 VTC(WHITE_SPACE/SPECIAL_CHAR/LENGTH_EXCEEDED/LENGTH_SHRUNK)는 findById 조회 실패로 PostNotFoundException 경로를 타므로 problem+json body까지 검증.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class InternalPostsByIdBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "ID_FULL", "full" + testId(info),
                "ID_NULLMOOD", "nullmood" + testId(info),
                "ID_HIGHLIKES", "hot" + testId(info),
                "ID_MISSING", "missing" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        executeSqlTemplate("sql/internal-posts-by-id-setup.sql", p);
    }

    @Test
    void NTC_getPost_success(TestInfo info) {
        // Happy path: 모든 필드가 채워진 post 정상 조회
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("ID_FULL"))
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200)
                    .body("id", containsString("full"))
                    .body("userId", equalTo("u-full-001"))
                    .body("title", equalTo("Full profile post"))
                    .body("category", equalTo("career"))
                    .body("content", equalTo("Body text for the full profile happy-path post."))
                    .body("moodEmoji", equalTo("😀"))
                    .body("nickname", equalTo("nick-full"))
                    .body("likes", equalTo(3))
                    .body("createdAt", containsString("2024-06-01"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getPost_nullMoodEmoji(TestInfo info) {
        // moodEmoji nullable 컬럼이 NULL인 post 정상 조회 (null 필드는 renderer 미지원으로 미검증)
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("ID_NULLMOOD"))
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200)
                    .body("id", containsString("nullmood"))
                    .body("userId", equalTo("u-null-002"))
                    .body("title", equalTo("Post without mood emoji"))
                    .body("category", equalTo("daily"))
                    .body("content", equalTo("Body text for the post that has no mood emoji set."))
                    .body("nickname", equalTo("nick-nullmood"))
                    .body("likes", equalTo(0))
                    .body("createdAt", containsString("2024-06-02"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getPost_highLikes(TestInfo info) {
        // likes 경계값(대용량 정수) post 정상 조회
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("ID_HIGHLIKES"))
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(200)
                    .body("id", containsString("hot"))
                    .body("userId", equalTo("u-hot-003"))
                    .body("title", equalTo("Extremely popular post"))
                    .body("category", equalTo("relationship"))
                    .body("content", equalTo("Body text for a post with a very high like count."))
                    .body("moodEmoji", equalTo("🔥"))
                    .body("nickname", equalTo("nick-popular"))
                    .body("likes", equalTo(9999))
                    .body("createdAt", containsString("2024-06-03"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_getPost_notFound(TestInfo info) {
        // DB에 존재하지 않는 id -> PostNotFoundException -> 404 problem+json
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", p.get("ID_MISSING"))
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", containsString("post not found"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_EMPTY(TestInfo info) {
        // RED id 변조 - EMPTY(NULL과 관측치 병합, docLines 참조): trailing slash -> 라우팅 단계 404
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_WHITE_SPACE(TestInfo info) {
        // RED id 변조 - WHITE_SPACE: trim 누락 버그 탐지
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "   ")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", containsString("post not found"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_SPECIAL_CHAR(TestInfo info) {
        // RED id 변조 - SPECIAL_CHAR: SQL injection 방어 검증 (JPA 파라미터 바인딩 안전)
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "'; DROP TABLE--")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", containsString("post not found"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_LENGTH_EXCEEDED(TestInfo info) {
        // RED id 변조 - LENGTH_EXCEEDED: DDL varchar(64) 초과(74자) 입력에도 크래시 없이 404
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", containsString("post not found"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_id_LENGTH_SHRUNK(TestInfo info) {
        // RED id 변조 - LENGTH_SHRUNK: 최소 길이(1자) 입력
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .pathParam("id", "A")
            .when()
                    .get("/internal/posts/{id}")
            .then()
                    .statusCode(404)
                    .body("title", equalTo("Post not found"))
                    .body("status", equalTo(404))
                    .body("detail", containsString("post not found"));
        } finally {
            executeSqlTemplate("sql/internal-posts-by-id-teardown.sql", p);
        }
    }
}

