21	 * 각 테스트 클래스에 인증 카탈로그 패턴으로 렌더된다.</p>
22	 */
23	public final class BlackBoxSupport {
24	
25	    private BlackBoxSupport() {
26	    }
27	
28	    public static final String BASE_URL =
29	            System.getProperty("test.server.url", "http://localhost:8085");
30	    public static final String WIREMOCK_URL =
31	            System.getProperty("test.wiremock.url", "http://localhost:9090");
32	
33	    private static final String DB_URL =
34	            System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/community");
35	    private static final String DB_USER =
36	            System.getProperty("test.db.user", "root");
37	    private static final String DB_PASSWORD =
38	            System.getProperty("test.db.password", "rootpw");
39	
40	    /** 병렬 안전: 매 호출마다 독립 Connection. */
41	    public static Connection getDbConnection() throws Exception {
42	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
43	    }
44	
45	    /** 메서드명 기반 결정적 고유 ID (재실행 시 동일값). */
46	    public static String testId(TestInfo info) {
47	        return String.format("T%09d",
48	                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
49	    }
50	
51	    /**
52	     * testId → 결정적 숫자 seq. 실 데이터와 겹치지 않도록 오프셋을 더한다.
53	     * 오프셋 기본값은 support-config.json 의 idOffset 로 주입된다 — 대상 DB PK가
54	     * 32-bit INT 이면 32비트 한계 내(예: 1_000_000_000)로 설정할 것.
55	     */
56	    public static long testSeq(TestInfo info) {
