63	    public static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
64	        try (InputStream is = BlackBoxSupport.class.getClassLoader().getResourceAsStream(resourcePath)) {
65	            if (is == null) {
66	                throw new IllegalStateException("SQL resource not found: " + resourcePath);
67	            }
68	            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
69	            for (Map.Entry<String, String> e : params.entrySet()) {
70	                sql = sql.replace("${" + e.getKey() + "}", e.getValue());
71	            }
72	            executeSqlScript(sql);
73	        } catch (RuntimeException e) {
74	            throw e;
75	        } catch (Exception e) {
76	            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
77	        }
78	    }
