80	    public static void executeSqlScript(String sql) {
81	        try (Connection conn = getDbConnection(); Statement stmt = conn.createStatement()) {
82	            StringBuilder current = new StringBuilder();
83	            for (String rawLine : sql.split("\n")) {
84	                String line = rawLine.trim();
85	                if (line.isEmpty() || line.startsWith("--")) {
86	                    continue;
87	                }
88	                current.append(line).append(' ');
89	                if (line.endsWith(";")) {
90	                    String stmtSql = current.toString().trim();
91	                    stmtSql = stmtSql.substring(0, stmtSql.length() - 1);
92	                    if (!stmtSql.isEmpty()) {
93	                        stmt.execute(stmtSql);
94	                    }
95	                    current.setLength(0);
96	                }
97	            }
98	            String tail = current.toString().trim();
99	            if (!tail.isEmpty()) {
100	                stmt.execute(tail);
101	            }
102	        } catch (Exception e) {
103	            throw new RuntimeException("SQL script execution failed", e);
104	        }
105	    }
106	
107	    /** 단일 스칼라 조회(첫 컬럼). 없으면 null. */
108	    public static String queryScalar(String sql, Object... args) {
109	        try (Connection conn = getDbConnection();
110	             PreparedStatement ps = conn.prepareStatement(sql)) {
111	            for (int i = 0; i < args.length; i++) {
112	                ps.setObject(i + 1, args[i]);
113	            }
114	            try (ResultSet rs = ps.executeQuery()) {
115	                if (rs.next()) {
116	                    return rs.getString(1);
117	                }
118	                return null;
119	            }
120	        } catch (Exception e) {
121	            throw new RuntimeException("queryScalar failed: " + sql, e);
122	        }
123	    }
124	}
